using System.ComponentModel;
using Microsoft.Extensions.AI;
using OpenAI;

// ── Tool state ──────────────────────────────────────────────────────────────
var notes = new List<string>();

// ── Tool definitions ────────────────────────────────────────────────────────

[Description("Search the web for information on a given query. Returns relevant snippets.")]
IReadOnlyList<string> SearchWeb(
    [Description("The search query")] string query)
{
    // Simulated results — swap in a real search API (Bing, Google, Tavily, etc.) for production.
    string[] results = query.ToLowerInvariant() switch
    {
        var q when q.Contains("quantum") => [
            "Quantum computing uses superposition and entanglement to perform calculations. Qubits can represent 0, 1, or both simultaneously, enabling massive parallelism for certain problems.",
            "IBM unveiled its 1,121-qubit Condor processor in 2024. Google's Willow chip demonstrated quantum error correction below threshold for the first time.",
            "Key applications include cryptography (Shor's algorithm can break RSA), drug discovery via molecular simulation, optimization for logistics, and materials science.",
            "Major challenges remain: qubit coherence times are short, error rates are high, and most useful algorithms require millions of logical qubits. Current machines have hundreds."
        ],
        var q when q.Contains("artificial intelligence") || q.Contains(" ai") || q.Contains("ai ") => [
            "Artificial intelligence (AI) simulates human intelligence in machines. Modern AI is dominated by deep learning and large language models (LLMs).",
            "LLMs like GPT-4, Claude, and Gemini demonstrate strong natural language understanding, code generation, and reasoning capabilities.",
            "AI safety research focuses on alignment, bias mitigation, interpretability, and preventing misuse. Regulatory frameworks are emerging worldwide."
        ],
        var q when q.Contains("climate") => [
            "Global average temperatures have risen ~1.1°C above pre-industrial levels. The Paris Agreement targets limiting warming to 1.5°C.",
            "Renewable energy capacity grew 50% in 2023, led by solar. Battery storage costs fell 90% over the past decade.",
            "Climate impacts include more frequent extreme weather, rising sea levels, and biodiversity loss. Adaptation strategies are increasingly important."
        ],
        _ => [
            $"Overview of '{query}': background information, history, and foundational concepts.",
            $"Recent developments in '{query}': current research, breakthroughs, and state of the art.",
            $"Future outlook for '{query}': expert predictions, open problems, and emerging trends."
        ]
    };

    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine($"  🔎 [SearchWeb] {results.Length} results for \"{query}\"");
    Console.ResetColor();

    return results;
}

[Description("Save a research note to record a key finding. Call this as you discover important information.")]
string SaveNote(
    [Description("The note content to save")] string content)
{
    notes.Add(content);
    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine($"  📝 [SaveNote] Note #{notes.Count} saved");
    Console.ResetColor();
    return $"Note saved (total notes: {notes.Count}).";
}

[Description("Retrieve all saved research notes so you can review findings before writing the summary.")]
string GetNotes()
{
    if (notes.Count == 0)
        return "No notes saved yet.";

    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine($"  📋 [GetNotes] Returning {notes.Count} note(s)");
    Console.ResetColor();

    return string.Join("\n", notes.Select((n, i) => $"[{i + 1}] {n}"));
}

// ── Build AI client with automatic function invocation ──────────────────────

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "";
var model  = Environment.GetEnvironmentVariable("OPENAI_MODEL")  ?? "gpt-4o-mini";

if (string.IsNullOrWhiteSpace(apiKey))
{
    Console.ForegroundColor = ConsoleColor.Red;
    Console.WriteLine("Error: Set the OPENAI_API_KEY environment variable.");
    Console.ResetColor();
    return;
}

IChatClient client = new ChatClientBuilder(
        new OpenAIClient(apiKey).GetChatClient(model).AsIChatClient())
    .UseFunctionInvocation()
    .Build();

ChatTool[] tools =
[
    AIFunctionFactory.Create(SearchWeb),
    AIFunctionFactory.Create(SaveNote),
    AIFunctionFactory.Create(GetNotes),
];

const string SystemPrompt = """
    You are a research agent. When the user gives you a topic, research it thoroughly:

    1. Break the topic into 2-3 sub-questions.
    2. Use SearchWeb to find information for each sub-question.
    3. Use SaveNote to record the most important findings as you go.
    4. After searching, use GetNotes to review everything you collected.
    5. Write a well-structured summary with sections and key takeaways.

    Always explain which findings support each section of your summary.
    """;

// ── Interactive loop ────────────────────────────────────────────────────────

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║        🔍 AI Research Agent          ║");
Console.WriteLine("╠══════════════════════════════════════╣");
Console.WriteLine("║  Enter a topic to research.          ║");
Console.WriteLine("║  Type 'quit' to exit.                ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("Research topic> ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    List<ChatMessage> messages =
    [
        new(ChatRole.System, SystemPrompt),
        new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
    ];

    Console.WriteLine();
    Console.ForegroundColor = ConsoleColor.Yellow;
    Console.WriteLine("Researching… (the agent will search and take notes)");
    Console.ResetColor();
    Console.WriteLine();

    try
    {
        var response = await client.GetResponseAsync(messages, new() { Tools = [.. tools] });

        Console.ForegroundColor = ConsoleColor.Green;
        Console.WriteLine("═══════ Research Summary ═══════");
        Console.ResetColor();
        Console.WriteLine(response.Text);
        Console.WriteLine();
    }
    catch (Exception ex)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.WriteLine($"Error: {ex.Message}");
        Console.ResetColor();
        Console.WriteLine();
    }

    notes.Clear();
}

Console.WriteLine("Goodbye!");

